class Ticket:
    def __init__(self, ticket_id: int, customer: str, title: str, priority: str, order: int) -> None:
        self.id = ticket_id
        self.customer = customer
        self.title = title
        self.priority = priority
        self.order = order
        self.closed = False
        self.in_queue = True


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}
        self._tickets: dict[int, Ticket] = {}
        # Queues per priority; index corresponds to PRIORITIES index (0: normal, 1: high, 2: critical)
        self._queues: dict[str, list[Ticket]] = {p: [] for p in self.PRIORITIES}
        self._next_id: int = 1
        self._order_counter: int = 0

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority '{priority}'. Must be one of {self.PRIORITIES}.")

        ticket_id = self._next_id
        self._next_id += 1

        order = self._order_counter
        self._order_counter += 1

        ticket = Ticket(
            ticket_id=ticket_id,
            customer=customer,
            title=title,
            priority=priority,
            order=order,
        )
        self._tickets[ticket_id] = ticket
        self._queues[priority].append(ticket)
        return ticket_id

    def next_ticket(self) -> int | None:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        for priority in reversed(self.PRIORITIES):
            queue = self._queues[priority]
            if queue:
                ticket = queue.pop(0)
                ticket.in_queue = False
                return ticket.id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket = self._tickets[ticket_id]
        ticket.closed = True

        if ticket.in_queue:
            self._queues[ticket.priority].remove(ticket)
            ticket.in_queue = False

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket = self._tickets[ticket_id]
        if ticket.closed:
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}.")

        if not ticket.in_queue:
            queue = self._queues[ticket.priority]
            # Maintain the original open order within the priority queue
            insert_pos = 0
            while insert_pos < len(queue) and queue[insert_pos].order < ticket.order:
                insert_pos += 1
            queue.insert(insert_pos, ticket)
            ticket.in_queue = True
